\u0043\u0049\u0046\u0057\u0047\u0075\u0034\u003f\u0037\u003b\u003c\u0057\u003c\u0032\u0029\u0023\u006a\u0042\u0039\u0074\u004d\u003f\u0071\u0029\u0063\u004e\u0033\u0035\u004a\u0029\u0048\u0037\u005d\u0028\u0028\u005b\u0061\u002e\u004a\u004a\u007b\u0049\u006c\u0036\u002a\u0046\u0029\u0044\u0056\u007a\u0064\u002e\u0041\u004c\u003e\u0033\u0060\u0064\u006c\u0077\u0023\u005d\u0069\u0021\u002b\u0039\u0073\u0062\u0058\u006c\u003c\u003e\u003f\u0045\u003e\u0078\u0039\u0042\u0079\u0022\u006e\u004c\u0055\u0030\u0079\u0031\u006c\u007a\u0074\u0070\u0050\u003f\u0075\u0074\u0046\u0053\u0055\u0053\u0047\u0067\u002a\u005d\u0067\u007b\u0059\u006e\u0068\u0066\u0021\u0025\u0076\u004d\u0062\u0024\u0065\u0059\u0039\u0026\u0046\u0069\u0070\u0031\u0045\u0046\u003d\u002b\u005d\u0060\u005d\u006f\u0045\u002f\u0054\u0038\u006b\u0032\u0049\u005e\u005d\u003e\u005d\u0048\u005b\u0040\u0040\u0023\u0048\u0065\u0024\u002a\u004c\u006d\u0078\u0074\u0052\u007c\u0060\u005b\u004b\u0030\u0070\u0034\u0039\u0025\u0059\u004c\u0068\u0045\u0079\u0021\u002e\u0047\u0057\u0055\u003f\u0051\u0056\u007d\u0045\u002f\u0054\u0030\u0049\u0061\u0031\u006c\u0047\u0057\u002a\u005a\u0042\u005d\u0055\u003b\u004c\u0049\u0032\u0072\u0045\u0029\u0072\u0074\u004c\u005e\u007d\u005e\u007d\u004c\u004c\u0043\u0074\u006c\u002b\u002b\u0059\u0041\u003c\u003a\u0042\u0024\u007b\u005d\u0040\u0067\u003c\u0026\u006c\u0051\u0035\u0029\u0047\u0046\u0056\u0069\u0059\u003d\u007c\u0062\u0043\u0061\u0075\u007b\u0077\u006c\u0059\u0035\u007e\u0025\u004b\u0062\u0059\u0047\u0056\u0073\u007c\u0024\u002b\u005e\u0048\u002f\u0061\u005f\u004d\u002a\u0074\u0030\u007b\u0031\u0077\u0047\u0044\u0056\u007b\u0059\u005b\u0069\u0074\u0056\u0030\u007b\u005e\u0037\u005d\u0031\u006e\u003d\u0023\u006b\u0065\u0043\u0061\u0071\u0056\u0043\u005d\u0030\u0044\u0053\u0023\u003e\u0042\u002e\u0079\u0077\u007e\u0048\u002b\u0044\u0023\u006d\u0040\u003f\u0068\u004c\u0052\u0071\u0070\u0070\u007e\u0023\u003e\u0025\u005b\u0034\u0056\u0038\u0075\u0065\u0069\u0025\u004b\u0041\u0062\u0061\u0060\u007e\u0064\u0070\u0046\u0060\u0029\u0028\u006b\u0065\u006f\u0040\u004d\u0041\u0065\u006e\u0059\u0055\u0023\u0042\u0033\u0039\u0076\u0043\u0078\u0076\u0066\u004e\u0037\u002f\u0056\u0036\u004a\u0058\u005e\u002e\u0072\u0062\u0057\u0033\u0061\u0034\u0049\u0064\u0053\u0021\u0050\u0055\u0059\u005f\u003c\u006f\u006b\u0063\u0053\u0070\u0053\u002e\u0023\u0067\u0067\u0051\u005e\u0043\u0052\u0031\u004b\u0048\u003b\u0026\u0043\u0043\u006c\u004e\u003a\u0036\u0029\u0058\u004d\u0051\u005f\u0060\u007b\u002b\u002f\u006d\u0055\u0078\u0057\u0045\u004e\u0034\u004c\u0070\u0049\u0078\u007b\u007d\u006b\u0028\u0053\u006e\u0054\u004a\u003f\u004e\u003d\u0079\u0042\u006d\u0070\u0051\u0056\u0077\u002a\u006b\u0031\u0058\u0033\u0062\u002b\u002b\u006e\u0040\u0049\u0053\u004e\u0024\u0062\u0065\u0070\u0038\u003b\u006a\u0045\u006e\u0059\u0055\u0075\u0040\u0049\u0069\u006e\u0035\u0052\u006c\u0065\u0059\u0033\u0062\u0029\u0060\u0033\u003c\u0043\u005a\u0025\u0044\u0061\u0074\u003a\u0060\u004a\u0059\u0033\u0062\u0029\u0072\u0065\u003c\u0043\u007e\u0034\u0059\u0038\u004c\u0059\u0051\u0051\u007e\u0066\u0021\u006e\u0037\u0025\u0061\u007b\u0025\u003e\u0042\u005e\u007d\u0057\u003b\u002c\u005b\u0070\u0066\u003a\u0060\u004a\u003f\u0021\u0044\u0022\u005e\u0076\u0068\u002e\u0048\u002c\u0061\u005e\u0037\u0055\u0041\u004a\u0044\u0066\u0034\u0075\u007a\u0035\u003a\u0074\u0040\u0049\u0058\u004e\u0024\u0062\u004a\u0070\u0078\u002f\u006a\u0045\u0077\u0038\u0068\u0043\u0060\u005d\u0072\u0078\u005f\u004b\u0029\u007c\u0079\u0046\u0063\u0053\u0076\u0053\u006d\u003a\u0067\u0067\u0026\u006d\u002b\u0055\u0041\u004a\u0044\u0066\u0034\u0075\u007a\u0035\u003a\u0074\u0040\u0049\u0058\u004e\u0039\u0062\u006e\u0042\u0077\u004b\u0063\u0053\u0057\u0053\u002e\u0023\u0067\u0067\u0051\u005e\u002b\u0055\u0047\u0075\u0055\u002c\u0065\u0045\u0062\u0057\u0028\u0030\u0059\u0022\u0048\u0044\u0072\u0033\u007b\u004b\u0070\u007e\u0063\u0064\u0042\u005e\u0036\u006d\u004e\u007c\u004c\u003c\u0059\u0053\u0071\u006e\u0038\u003b\u006a\u0045\u006f\u0065\u0068\u0043\u0022\u0025\u007a\u0035\u0056\u0074\u0040\u0049\u0053\u004e\u007a\u0055\u003e\u0070\u006c\u005d\u004c\u0074\u0023\u003d\u0028\u0030\u003a\u0032\u0065\u0030\u0062\u0041\u006e\u0037\u006f\u0076\u003e\u007e\u0031\u0055\u0078\u0039\u006b\u004b\u0059\u0023\u006d\u0043\u0054\u0075\u006b\u0057\u0036\u0048\u0064\u0070\u003a\u0075\u0040\u0049\u0069\u006e\u0041\u007b\u0058\u0056\u0069\u0052\u0051\u0061\u0036\u0068\u0067\u0058\u0060\u0059\u0044\u003e\u005a\u006d\u0026\u0038\u0062\u0061\u007c\u004f\u007b\u005b\u0046\u0063\u0039\u0048\u006c\u0075\u0034\u0053\u0078\u005a\u0079\u0026\u0079\u0052\u005d\u0033\u0057\u007e\u004b\u007c\u0057\u0077\u006a\u0070\u0048\u002c\u004a\u0049\u0043\u0052\u0063\u007a\u0052\u0044\u0065\u0041\u0053\u0065\u007d\u002b\u0055\u004d\u003b\u0026\u0050\u0079\u006b\u005a\u006c\u0032\u0058\u0041\u004a\u002f\u003c\u0034\u006f\u0048\u0059\u0048\u006b\u0063\u0059\u004d\u003c\u002a\u005b\u0040\u0036\u0031\u006b\u0064\u0022\u0074\u005f\u002c\u0068\u006d\u0022\u0030\u0067\u0033\u0073\u0053\u0069\u006e\u0038\u003b\u0042\u0045\u006f\u0065\u0068\u0043\u0022\u0025\u007a\u0035\u0056\u0074\u0040\u0049\u0053\u004e\u0024\u0062\u0065\u0070\u0038\u003b\u006a\u0045\u006f\u0065\u0068\u0043\u0022\u0025\u007a\u0035\u0056\u0074\u0040\u0049\u0053\u004e\u0024\u0062\u0065\u0070\u0038\u003b\u006a\u0045\u006f\u0065\u0068\u0043\u0022\u0025\u007a\u0035\u0056\u0074\u0040\u0049\u0053\u004e\u0024\u0062\u0065\u0070\u0038\u003b\u006a\u0045\u006f\u0065\u0068\u0043\u0022\u0025\u007a\u0035\u0056\u0074\u0040\u0049\u0053\u004e\u0067\u0065\u0052\u006b\u007c\u0024\u003a\u0074\u0077\u006d\u003a\u0039\u0077\u0064\u006c\u0051\u0060\u0041\u0054\u0032\u0050\u004f\u0065\u0026\u0074\u005d\u0043\u0037\u0046\u004b\u002b\u0033\u0061\u0041\u004d\u005e\u0065\u0024\u0047\u0024\u0038\u005d\u002a\u0072\u0064\u007b\u004c\u0046\u0049\u006b\u0026\u0076\u0024\u003a\u0058\u005d\u0059\u0059\u0030\u0072\u0043\u0038\u004b\u0045\u0038\u0054\u003b\u0071\u003b\u0029\u0073\u006f\u007a\u0032\u0071\u0060\u0030\u005b\u004a\u0034\u004e\u007c\u0029\u0038\u0068\u0070\u0035\u0037\u0037\u0078\u0057\u0059\u0058\u0051\u004b\u0079\u007a\u0022\u0025\u0030\u0072\u0052\u007d\u0070\u003b\u007e\u0073\u005b\u003a\u0069\u0025\u0039\u0044\u004e\u0036\u0033\u0044\u0057\u002b\u003e\u0070\u005b\u0039\u0050\u004b\u004c\u007c\u005b\u006e\u0060\u0031\u0035\u0032\u0048\u0039\u0048\u003f\u005e\u006a\u006a\u002b\u0054\u0022\u005a\u0040\u0053\u0055\u0024\u003a\u0022\u0022\u0038\u004e\u0036\u0052\u0061\u005f\u005d\u002b\u006e\u0030\u004a\u0026\u0029\u002a\u007b\u0025\u0050\u0047\u004e\u007c\u003c\u0039\u005b\u0025\u004a\u0074\u0035\u007e\u0048\u0058\u0046\u0037\u002c\u004e\u0073\u003e\u0051\u002a\u0039\u002b\u0057\u0028\u0056\u0035\u0040\u005f\u004b\u0042\u0026\u0026\u0058\u0062\u005b\u0048\u004e\u0023\u0042\u0034\u0039\u004d\u0024\u006d\u0047\u0058\u0064\u007b\u0070\u0062\u005b\u0066\u0058\u0059\u005a\u0038\u0034\u0064\u004b\u0042\u0061\u0030\u004b\u0060\u0022\u0071\u0033\u0075\u004c\u006c\u0036\u0030\u0037\u0064\u004b\u0023\u0071\u005d\u0058\u0047\u0021\u004b\u0038\u0045\u0059\u0036\u0071\u0055\u005d\u0058\u0030\u004f\u005b\u003f\u0025\u0062\u002e\u004b\u0068\u004d\u0046\u0074\u0040\u0024\u0044\u002a\u005b\u0048\u0041\u0025\u006c\u0042\u0061\u004f\u004e\u0076\u0032\u0048\u0039\u0048\u003f\u005e\u006a\u006a\u002b\u0054\u0026\u007b\u007d\u0070\u0075\u006b\u0022\u0071\u0061\u004f\u004e\u0076\u0032\u0048\u0039\u0048\u003f\u005e\u006a\u006a\u002b\u0054\u0026\u007b\u007d\u0070\u0075\u006b\u0022\u0071\u0061\u004f\u004e\u0076\u0032\u0048\u0039\u0048\u003f\u005e\u006a\u006a\u002b\u0054\u0026\u007b\u007d\u0070\u0075\u006b\u0022\u0071\u0061\u004f\u004e\u0076\u0032\u0048\u0039\u0048\u003f\u005e\u0079\u0034\u0023\u005a\u004c\u0052\u0075\u005b\u0035\u003a\u007a\u0023\u0036\u005f\u0072\u005e\u006b\u0058\u0041\u004b\u0076\u002e\u003e\u0062\u0054\u0054\u0069\u006b\u0070\u0043\u007b\u0066\u0057\u0024\u0045\u005d\u0031\u005b\u0034\u002e\u002e\u0034\u007a\u0023\u0048\u0075\u0030\u0073\u003b\u0065\u006d\u0031\u0075\u0035\u0052\u003d\u007a\u0065\u003b\u0060\u0024\u0037\u0066\u0022\u0070\u0034\u0059\u0022\u0033\u002c\u007b\u0038\u0039\u0045\u0045\u0042\u003d\u0035\u003b\u003b\u0054\u0051\u0038\u0063\u007c\u003d\u0042\u007d\u002a\u002c\u0074\u0035\u0039\u0022\u0061\u0064\u004a\u0036\u004e\u005e\u0053\u0073\u006d\u0047\u0059\u0036\u0024\u003f\u0056\u006f\u0067\u0071\u0024\u005f\u005f\u0065\u004c\u006f\u0025\u0055\u004c\u0078\u004e\u0037\u003a\u002b\u0064\u0059\u0037\u005a\u0031\u0076\u004a\u004f\u004b\u0066\u006b\u003f\u0059\u0069\u0071\u0076\u0059\u0060\u0077\u003b\u0061\u0061\u0055\u0031\u0068\u0059\u006a\u006e\u006d\u002c\u003b\u0056\u007e\u0022\u002c\u006e\u0044\u0050\u0045\u0030\u0079\u0076\u006a\u005e\u0050\u0053\u002b\u0060\u0066\u006b\u003f\u0024\u004d\u0076\u006a\u0054\u0053\u0021\u005d\u0050\u0063\u0045\u0039\u0077\u006d\u0046\u0051\u0074\u0075\u006c\u0075\u007c\u0071\u0045\u0079\u0070\u0045\u005e\u006a\u0032\u005e\u002f\u0072\u0046\u003a\u005e\u0053\u0059\u006a\u006e\u006d\u002c\u0036\u0021\u0067\u0057\u0041\u0028\u0040\u004d\u0068\u0059\u0065\u005e\u002c\u005a\u0023\u007b\u0059\u0025\u0046\u0043\u007e\u003a\u003c\u0032\u0040\u005e\u0044\u0028\u006a\u0063\u0042\u006d\u0031\u0044\u003c\u0076\u0039\u002a\u0033\u0054\u0054\u0073\u0041\u007b\u003c\u0056\u004c\u004b\u004f\u003b\u0077\u0023\u0061\u002a\u0048\u003c\u005a\u0045\u0035\u006a\u005f\u004e\u0037\u0037\u002c\u004e\u007d\u003e\u003e\u0031\u004d\u0047\u005a\u0030\u0041\u0055\u0071\u005a\u003e\u004b\u004f\u0026\u007d\u0056\u0045\u0070\u0044\u007e\u0070\u0079\u005e\u002f\u0054\u002a\u007b\u006e\u005e\u007b\u0036\u0046\u006b\u0052\u0052\u0074\u007d\u0054\u0022\u0055\u002a\u0066\u0039\u0032\u0025\u0068\u006f\u0079\u007d\u0077\u003c\u0041\u0076\u0077\u0055\u002a\u0070\u0025\u0062\u005f\u0035\u0038\u0060\u0079\u0032\u0060\u0025\u006d\u007c\u002c\u005d\u0047\u0045\u0021\u0068\u0074\u007b\u003c\u0035\u0071\u003d\u0074\u0037\u005b\u007c\u0051\u0057\u0064\u0031\u0075\u0028\u007d\u0036\u0068\u0046\u0067\u004f\u0055\u0061\u006c\u0031\u007b\u0054\u0022\u0030\u003b\u004e\u0042\u002b\u0059\u003b\u0057\u007d\u0021\u002c\u007d\u0067\u0060\u0032\u002f\u0071\u0047\u0032\u005d\u0034\u0022\u0029\u0046\u007e\u0042\u0059\u0044\u005d\u004b\u0066\u003b\u007d\u0068\u0045\u0046\u0046\u0031\u0067\u006a\u002e\u0050\u0062\u0077\u0033\u0022\u0040\u007e\u0026\u0030\u0079\u0060\u0077\u0072\u004f\u0034\u0071\u0065\u007d\u005f\u005d\u0061\u0064\u0059\u0055\u0035\u0044\u006a\u0045\u0071\u003d\u0043\u0051\u005f\u0063\u0031\u0034\u0032\u003b\u0075\u0053\u0046\u003c\u0076\u004c\u0054\u006b\u007d\u0039\u0026\u003c\u0077\u0075\u0061\u0059\u0072\u0029\u0058\u0047\u0033\u0070\u0041\u0070\u002a\u002c\u003a\u0048\u0064\u0030\u0046\u0044\u006b\u0039\u002c\u004d\u0039\u003a\u0078\u005f\u002a\u0069\u0046\u0048\u0035\u0042\u003d\u007c\u002f\u0065\u0046\u004f\u0041\u004a\u0053\u0060\u0028\u003c\u003e\u003a\u0059\u0026\u004b\u003c\u0038\u0054\u0039\u0042\u007d\u003f\u0022\u0032\u0024\u0079\u0050\u0069\u006c\u0048\u0047\u0057\u002b\u0079\u0057\u002e\u0025\u0050\u0026\u0028\u0074\u0064\u004e\u0048\u0063\u002a\u007a\u0074\u0022\u0053\u007d\u0067\u0042\u0024\u0024\u0039\u0043\u0033\u0060\u0064\u0064\u003e\u0051\u002a\u0071\u0056\u003a\u0069\u0036\u005d\u002a\u007c\u0021\u0044\u0034\u0064\u005b\u004e\u0047\u0058\u003e\u0059\u0025\u0048\u0068\u0039\u004d\u005d\u002a\u002b\u0028\u0045\u006e\u006c\u002f\u006c\u0060\u004e\u0062\u002b\u003c\u0072\u005f\u0076\u0040\u0040\u0029\u0039\u0052\u006c\u0065\u006a\u0078\u0040\u006c\u002a\u0057\u0073\u0052\u003a\u005b\u0054\u0063\u0073\u005d\u0022\u003e\u0052\u004f\u0044\u0051\u0023\u006c\u0072\u003a\u006f\u005d\u0062\u004e\u0022\u0072\u0025\u003e\u0041\u0042\u0041\u007c\u0036\u006a\u0063\u0032\u0050\u0036\u0079\u006e\u0031\u0041\u0056\u003d\u0062\u0045\u0035\u002c\u0036\u006c\u006c\u0024\u003d\u0041\u0036\u007c\u0025\u0069\u003d\u004b\u0064\u0037\u0046\u0042\u0041\u0030\u0050\u0051\u0035\u0052\u0044\u0031\u0033\u0062\u0059\u004e\u004d\u0041\u0059\u0028\u0035\u0052\u0048\u0040\u0030\u0033